def head(filename, title, description, questions):
    production = bool(site_url) and filename not in ('impressum.html', 'datenschutz.html', 'werbung.html')
    url = site_url + ('/' if filename == 'index.html' else '/' + filename) if site_url else ''
    metadata = f'<meta name="description" content="{html.escape(description, quote=True)}"><meta name="robots" content="{"index,follow,max-image-preview:large" if production else "noindex,follow"}">'
    metadata += f'<meta property="og:type" content="website"><meta property="og:locale" content="de_DE"><meta property="og:site_name" content="CreedStreetStudios47"><meta property="og:title" content="{html.escape(title, quote=True)}"><meta property="og:description" content="{html.escape(description, quote=True)}"><meta name="twitter:card" content="summary_large_image">'
    schema = {'@context': 'https://schema.org', '@type': 'WebPage', 'name': title, 'description': description, 'inLanguage': 'de-DE', 'about': {'@type': 'Organization', 'name': 'CreedStreetStudios47', 'description': 'Independent-Musiklabel- und Studio-Konzept aus Duisburg', 'areaServed': {'@type': 'Place', 'name': 'Duisburg und Ruhrgebiet'}, 'sameAs': ['https://suno.com/@creedstreetstudios47']}}
    if site_url:
        metadata += f'<link rel="canonical" href="{html.escape(url, quote=True)}"><meta property="og:url" content="{html.escape(url, quote=True)}"><meta property="og:image" content="{html.escape(site_url, quote=True)}/assets/hero-vinyl.png">'
        schema['url'] = url
    return f'<!doctype html><html lang="de"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0b0f"><title>{html.escape(title)}</title>{metadata}<link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="stylesheet" href="style.css?v=schwarzes-eisen-1"><script type="application/ld+json">{json.dumps(schema, ensure_ascii=False)}</script><script src="public-settings.js" defer></script><script src="app.js" defer></script><script src="sound.js?v=schwarzes-eisen-1" defer></script><script src="connect.js?v=schwarzes-eisen-1" defer></script></head>'


def render(filename, title, description, content, questions):
    nav = ''.join(f'<a class="nav-link" href="{url}"' + (' aria-current="page"' if url == filename else '') + f'>{label}</a>' for url, label in links)
    page_header = re.sub(r'<nav id="navigation".*?</nav>', f'<nav id="navigation" aria-label="Hauptnavigation">{nav}</nav>', header)
    page_header = page_header.replace('href="#"', 'href="index.html"')
    sound = '<audio id="background-sound" src="assets/audio/schwarzes-eisen.mp3" preload="none" loop hidden aria-hidden="true"></audio><button class="sound-switch" id="sound-toggle" type="button" aria-pressed="false" aria-label="Schwarzes Eisen: Hintergrundmusik einschalten"><span class="sound-bars" aria-hidden="true"><i></i><i></i><i></i></span><span><strong id="sound-label">Sound an</strong><small>Schwarzes Eisen</small></span></button><span id="sound-notice" class="sr-only" role="status"></span>'
    document = head(filename, title, description, questions) + '<body>' + icons + '<a class="skip-link" href="#main">Zum Inhalt</a>' + page_header + '<main id="main">' + content + '</main>' + footer + sound + dialogs + '</body></html>'
    (ROOT / filename).write_text(document)

home = base[base.index('<main id="main">') + len('<main id="main">'):base.index('</main>')]
home = home.replace('<button class="card-link" data-project="Studio & Produktion">', '<a class="card-link" href="studio.html">').replace('<button class="card-link" data-project="Digitaler Vertrieb">', '<a class="card-link" href="vertrieb.html">').replace('<button class="card-link" data-project="Label & Artist-Entwicklung">', '<a class="card-link" href="ueber-uns.html">')
home = re.sub(r'(<a class="card-link".*?</svg>)</button>', r'\1</a>', home)
home = home.replace('<section class="vision', '<div class="page-routes section-wrap"><a href="studio.html"><span>01 / CREATE</span>Studio entdecken ↗</a><a href="vertrieb.html"><span>02 / RELEASE</span>Label & Vertrieb ↗</a><a href="kontakt.html"><span>03 / CONNECT</span>Kontakt & Socials ↗</a></div><section class="vision', 1)
render('index.html', 'CreedStreetStudios47 | Musikstudio & Label aus Duisburg', 'Musikstudio, Independent-Label und digitale Release-Planung aus Duisburg. Rap, Drill, Recording, Mixing und Mastering: entdecke die Vision von CreedStreetStudios47.', home, [])
# Reuse the same minimal Suno link on the studio page.
