for filename, (title, description, content, questions) in pages.items():
    content = content.replace(old_sound, new_sound)
    content = content.replace('href="#kontakt"', 'href="kontakt.html"')
    render(filename, title, description, content, questions)

if site_url:
    entries = ''.join(f'<url><loc>{html.escape(site_url + ("/" if name == "index.html" else "/" + name))}</loc></url>' for name in ['index.html', 'studio.html', 'vertrieb.html', 'ueber-uns.html', 'kontakt.html'])
